mapper.select:
SELECT A.ENTRUST_STATUS AS entrustStatus, A.PRICE * 100 AS price, ROUND(NVL(T5.FINISH_AMT,0)/(A.ENTRUST_AMT),4)*100 AS transactioncom, ROUND(NVL(IQC.totalShareAmt,0)/(A.ENTRUST_AMT),4)*100 AS tradeFinishPercent, A.INV_MANAGER_ID AS invManagerId, (SELECT real_name FROM SYS_USER WHERE user_name = A.INV_MANAGER_ID) AS invManagerName, A.PORTFOLIO_ID AS portfolioId, B.PORTFOLIO_NAME AS portfolioName, C.SEC_ACCT_ID AS secAcctId, D.SEC_ACCT_NAME AS secAcctName, A.PS AS ps, A.CCY AS ccy, NVL(T1.PARTY_ID,A.COUNTER_ID) AS counterId, A.COUNTER_TRADER AS counterTrader, A.ENTRUST_AMT AS entrustNum, NVL(T5.FINISH_AMT,0) AS finishAmt, (A.ENTRUST_AMT -NVL(T5.FINISH_AMT,0) ) AS avaNum, A.VDATE AS vdate, A.MDATE AS mdate, C.VDATE AS repoVdate, C.MDATE AS repoMdate, C.TERM_DAYS AS term, A.ENTRUST_ID AS entrustId, NVL2(C.SETTLE_SPREED, CONCAT('0',C.SETTLE_SPREED+1), NULL) AS settleSpreed, NVL(F.PARTY_ID, FF.PARTY_ID) AS mySide, NVL(G.PARTY_ABBR, GG.PARTY_ABBR) AS mySideAbbr, (SELECT MST_CFETS_CUSTOMER_TRADER.TRADER_ID FROM MST_CFETS_CUSTOMER_TRADER INNER JOIN SYS_USER_ADD ON SYS_USER_ADD.ibu_trader = MST_CFETS_CUSTOMER_TRADER.TRADER_ID INNER JOIN SYS_USER ON sys_user.user_name = '${loginUserId}' AND sys_user.USER_ID = SYS_USER_ADD.USER_ID WHERE MST_CFETS_CUSTOMER_TRADER.MPARTY_ID = NVL(G.PARTY_ID, GG.PARTY_ID) OR MST_CFETS_CUSTOMER_TRADER.MPARTY_ID = ( SELECT MST_CFETS_CUSTOMER_RELA.MPARTY_ID FROM MST_CFETS_CUSTOMER_RELA WHERE MST_CFETS_CUSTOMER_RELA.SPARTY_ID = NVL(G.PARTY_ID, GG.PARTY_ID)) ) AS mySideTrader ,
(SELECT MST_CFETS_CUSTOMER_TRADER.TRADER_NAME FROM MST_CFETS_CUSTOMER_TRADER INNER JOIN SYS_USER_ADD ON SYS_USER_ADD.ibu_trader = MST_CFETS_CUSTOMER_TRADER.TRADER_ID INNER JOIN SYS_USER ON sys_user.user_name = '${loginUserId}' AND sys_user.USER_ID = SYS_USER_ADD.USER_ID WHERE MST_CFETS_CUSTOMER_TRADER.MPARTY_ID = nvl(G.PARTY_ID, GG.PARTY_ID) OR MST_CFETS_CUSTOMER_TRADER.MPARTY_ID = ( SELECT MST_CFETS_CUSTOMER_RELA.MPARTY_ID FROM MST_CFETS_CUSTOMER_RELA WHERE MST_CFETS_CUSTOMER_RELA.SPARTY_ID = nvl(G.PARTY_ID, GG.PARTY_ID)) ) mySideTraderName, C.TERM_TYPE, pp.PORTFOLIO_SERIES portfolioSeries FROM ETR_ENTRUST A INNER JOIN PTL_PORTFOLIO B ON A.PORTFOLIO_ID = B.PORTFOLIO_ID LEFT JOIN ETR_ENTRUST_ADD C ON A.ENTRUST_ID = C.ENTRUST_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_QUOTE_FINISH_STATUS
where QUOTE_ID != #{currQuoteId}
GROUP BY ENTRUST_ID) T5 ON A.ENTRUST_ID = T5.ENTRUST_ID LEFT JOIN STL_SEC_ACCT_INFO D ON C.SEC_ACCT_ID = D.SEC_ACCT_ID LEFT JOIN ETR_DISTRIBUTE E ON A.ENTRUST_ID = E.ENTRUST_ID
LEFT JOIN IBU_PORTFOLIO_ACCT_RELA F ON A.PORTFOLIO_ID = F.PORTFOLIO_ID AND F.CFETS_ACCT_TYPE = #{secAcctSource01} LEFT JOIN MST_CFETS_CUSTOMER_INFO G ON F.PARTY_ID = G.PARTY_ID
LEFT JOIN IBU_PORTFOLIO_ACCT_RELA FF ON A.PORTFOLIO_ID = FF.PORTFOLIO_ID AND FF.CFETS_ACCT_TYPE = #{secAcctSource02} LEFT JOIN MST_CFETS_CUSTOMER_INFO GG ON FF.PARTY_ID = GG.PARTY_ID LEFT JOIN SYS_USER H ON A.CREATE_USER = H.USER_NAME
LEFT JOIN (SELECT ENTRUST_ID,SUM(nvl(FPRICE_AMT,0)) totalShareAmt FROM IBU_QUOTE_CREP WHERE TRADE_STATUS = '07' GROUP BY ENTRUST_ID) IQC ON IQC.ENTRUST_ID = A.ENTRUST_ID
left join MST_CFETS_CUSTOMER_TRADER T2 ON T2.TRADER_ID = A.COUNTER_TRADER left join MST_CFETS_CUSTOMER_INFO T1 ON T1.PARTY_ID = T2.PARTY_ID LEFT JOIN PA_PTL_PORTFOLIO pp ON B.PORTFOLIO_ID = pp.PORTFOLIO_ID left join FIN_PRODUCT fp on A.FINPROD_ID = fp.FINPROD_ID
where A.ENTRUST_STATUS IN (#{entrustStatusUnAccept}, #{entrustStatusAccept}, #{entrustStatusComple}) AND A.PS IN (#{ps03},#{ps04}) AND A.TRADE_MARKET = #{tradeMarket} AND A.FINPROD_TYPE2 in (#{FINPROD_TYPE2_Z},#{FINPROD_TYPE2_N}) AND E.TRADER = #{loginUserId}
AND A.ENTRUST_STATUS = #{entrustStatusUnAccept}
AND A.ENTRUST_STATUS = #{entrustStatusAccept} AND NVL(T5.FINISH_AMT,0) < A.ENTRUST_AMT
AND ((A.ENTRUST_STATUS = #{entrustStatusAccept} AND NVL(T5.FINISH_AMT,0) >= A.ENTRUST_AMT) OR A.ENTRUST_STATUS = #{entrustStatusComple} )
AND A.PORTFOLIO_ID IN
#{item}
AND fp.FINPROD_MARKET_ID IN
#{item}
AND A.PS = #{ps_zlgl}
AND A.INV_MANAGER_ID IN
#{item}
order by A.VDATE desc

SELECT TABLE01.PORTFOLIO_ID portfolioId,/*组合代码*/ pp.PORTFOLIO_NAME portfolioName,/*组合名称*/ TABLE01.SEC_ACCT_ID secAcctId,/*证券账户/通道代码*/ ssai.SEC_ACCT_NAME secAcctName, NVL(TABLE02.AMOUNT,0) * 100 posStrdPrinAmt,/*持仓券面总额*/ NVL(TABLE01.AMOUNT,0) * 100 pledStrdPrinAmt,/*可质押券面总额*/ FIN_PRODUCT.TRADE_MARKET tradePlace,/*交易场所*/ ETR_ENTRUST_PLEDGE.SCALE pledgeRate, /*折算比例*/ FIN_PRODUCT.MDATE mdate,/*到期日*/ FIN_PRODUCT.REGIST_ORG registOrg,/*登记托管机构*/ MST_BOND_VALUATION_INFO.LAST_PERIOD lastPeriod,/*剩余期限*/ mbcr.O_TYPE gradeResult,/*债项评级*/ NVL(FIN_PRODUCT.FINPROD_ABBR,FIN_PRODUCT.FINPROD_NAME) bondAbbrName,/*债券名称*/ FIN_PRODUCT.FINPROD_MARKET_ID bondCode/*债券代码*/ FROM ETR_ENTRUST_PLEDGE LEFT JOIN ( SELECT TEMP.PORTFOLIO_ID,/*组合代码*/ TEMP.SEC_ACCT_ID,/*证券账户/通道代码*/ TEMP.FINPROD_ID,/*金融产品Id*/ TEMP.BRANCH,/*分支序号*/ SUM(TEMP.AMOUNT) AMOUNT /*可质押券面总额*/ FROM ( SELECT PTL_SEC_POSITION.PORTFOLIO_ID, PTL_SEC_POSITION.SEC_ACCT_ID, PTL_SEC_POSITION.FINPROD_ID, PTL_SEC_POSITION.BRANCH, CASE WHEN PTL_SEC_POSITION.HODING_TYPE IN (#{POSITION_TYPE_03},#{POSITION_TYPE_05},#{POSITION_TYPE_08})then PTL_SEC_POSITION.AMOUNT ELSE -1 * PTL_SEC_POSITION.AMOUNT END as AMOUNT FROM PTL_SEC_POSITION WHERE 1=1 AND PTL_SEC_POSITION.CDATE = to_date(#{plateDate},'yyyy-MM-dd')/*组合持仓.日期 = 平台日*/ /*持仓类型包含：03实际，04质押，05融入，06融出，08预占用,11卖空*/ AND PTL_SEC_POSITION.HODING_TYPE IN (#{POSITION_TYPE_03}, #{POSITION_TYPE_04},#{POSITION_TYPE_05}, #{POSITION_TYPE_06},#{POSITION_TYPE_08},#{POSITION_TYPE_11})
UNION ALL SELECT PTL_SEC_POSITION_FLOW.PORTFOLIO_ID, PTL_SEC_POSITION_FLOW.SEC_ACCT_ID, PTL_SEC_POSITION_FLOW.FINPROD_ID, PTL_SEC_POSITION_FLOW.BRANCH, CASE WHEN PTL_SEC_POSITION_FLOW.HODING_TYPE IN (#{POSITION_TYPE_01})then PTL_SEC_POSITION_FLOW.AMOUNT ELSE -1 * PTL_SEC_POSITION_FLOW.AMOUNT END as AMOUNT FROM PTL_SEC_POSITION_FLOW WHERE 1=1 AND PTL_SEC_POSITION_FLOW.CDATE = to_date(#{plateDate},'yyyy-MM-dd')/*组合持仓.日期 = 平台日*/ /*持仓类型包含：01可用，12卖空可用*/ AND PTL_SEC_POSITION_FLOW.HODING_TYPE IN (#{POSITION_TYPE_01}, #{POSITION_TYPE_12}) ) TEMP GROUP BY TEMP.PORTFOLIO_ID, TEMP.SEC_ACCT_ID, TEMP.FINPROD_ID, TEMP.PORTFOLIO_ID, TEMP.BRANCH HAVING SUM(TEMP.AMOUNT) > 0/*只统计可质押券面总额>0*/ )TABLE01/*以上统计可用持仓*/ ON ETR_ENTRUST_PLEDGE.PORTFOLIO_ID = TABLE01.PORTFOLIO_ID AND ETR_ENTRUST_PLEDGE.FINPROD_ID = TABLE01.FINPROD_ID AND ETR_ENTRUST_PLEDGE.BRANCH = TABLE01.BRANCH AND ETR_ENTRUST_PLEDGE.SEC_ACCT_ID = TABLE01.SEC_ACCT_ID LEFT JOIN ( SELECT PTL_SEC_POSITION.PORTFOLIO_ID, PTL_SEC_POSITION.SEC_ACCT_ID, PTL_SEC_POSITION.FINPROD_ID, PTL_SEC_POSITION.BRANCH, SUM( CASE WHEN PTL_SEC_POSITION.HODING_TYPE IN (#{POSITION_TYPE_03},#{POSITION_TYPE_05})then PTL_SEC_POSITION.AMOUNT ELSE -1 * PTL_SEC_POSITION.AMOUNT END) as AMOUNT FROM PTL_SEC_POSITION WHERE 1=1 AND PTL_SEC_POSITION.CDATE = to_date(#{plateDate},'yyyy-MM-dd')/*组合持仓.日期 = 平台日*/ /*持仓类型包含：03实际，05融入，06融出,11卖空*/ AND PTL_SEC_POSITION.HODING_TYPE IN (#{POSITION_TYPE_03},#{POSITION_TYPE_05}, #{POSITION_TYPE_06},#{POSITION_TYPE_11}) GROUP BY PTL_SEC_POSITION.PORTFOLIO_ID, PTL_SEC_POSITION.SEC_ACCT_ID, PTL_SEC_POSITION.FINPROD_ID, PTL_SEC_POSITION.PORTFOLIO_ID, PTL_SEC_POSITION.BRANCH )TABLE02 /*以上统计实际持仓*/ ON ETR_ENTRUST_PLEDGE.PORTFOLIO_ID = TABLE02.PORTFOLIO_ID AND ETR_ENTRUST_PLEDGE.FINPROD_ID = TABLE02.FINPROD_ID AND ETR_ENTRUST_PLEDGE.BRANCH = TABLE02.BRANCH AND ETR_ENTRUST_PLEDGE.SEC_ACCT_ID = TABLE02.SEC_ACCT_ID INNER JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = TABLE01.FINPROD_ID
AND FIN_PRODUCT.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01}
LEFT JOIN ( SELECT T2.SEC_ID, T2.LAST_PERIOD FROM ( SELECT tmp1.SEC_ID, tmp1.value_source, MAX(tmp1.value_date) AS value_date FROM MST_BOND_VALUATION_INFO tmp1 LEFT JOIN FIN_PRODUCT tmp2 ON tmp1.sec_id = tmp2.finprod_market_id WHERE 1 = 1 AND tmp1.value_date <= to_date(#{plateDate},'yyyy-MM-dd')/*估值行情.日期 小于等于 平台日*/ AND tmp1.value_source = (CASE WHEN tmp2.trade_market IN (#{TRADEPLACE03},#{TRADEPLACE04}) THEN 'CSD' ELSE 'CBC' END) GROUP BY tmp1.sec_id, tmp1.value_source ) T1 LEFT JOIN MST_BOND_VALUATION_INFO T2 ON T1.SEC_ID = T2.SEC_ID AND T1.value_source = T2.value_source AND T1.VALUE_DATE = T2.VALUE_DATE ) MST_BOND_VALUATION_INFO ON FIN_PRODUCT.FINPROD_MARKET_ID = MST_BOND_VALUATION_INFO.SEC_ID left join PTL_PORTFOLIO pp on TABLE01.PORTFOLIO_ID = pp.PORTFOLIO_ID left join MST_BOND_CREDIT_RATING mbcr on FIN_PRODUCT.FINPROD_MARKET_ID = mbcr.O_CODE and mbcr.O_TYPE = '02' left join STL_SEC_ACCT_INFO ssai on TABLE01.SEC_ACCT_ID = ssai.SEC_ACCT_ID /*以上获取债券小于等于平台日的最新估值行情*/ WHERE 1=1 /*只获取交易场所为：01银行间，03上海证券交易所,04深圳证券交易所*/ AND FIN_PRODUCT.TRADE_MARKET IN (#{TRADEPLACE01},#{TRADEPLACE03},#{TRADEPLACE04})
AND ETR_ENTRUST_PLEDGE.PORTFOLIO_ID IN
#{item}
AND (ETR_ENTRUST_PLEDGE.SEC_ACCT_ID in
null) or ETR_ENTRUST_PLEDGE.SEC_ACCT_ID in (
#{item}
)

select distinct aa.* from( SELECT /*add by chenjiaxing 质押式回购改造 20210819*/ I.COUNTERTRADERNAME counterTraderName,/*对方交易员*/ I.SETTLDATE settldate, /*首次结算日*/ I.SETTLDATE2 settldate2,/*到期结算日*/ ptl_portfolio.Portfolio_Id portfolioId,/*组合代码*/ ptl_portfolio.portfolio_name portfolioName,/*组合名称*/ I.DELIVERYTYPE deliveryType,/*首次结算方式*/ I.DELIVERYTYPE2 deliveryType2,/*到期结算方式*/ I.TRADEMETHOD tradeMethod,/*交易方式*/ I.SETTLCURRENCY settlcurrency,/*结算币种*/ I.EXECTYPE execType,/*成交状态*/ I.OURINSTITUTIONCODE ourinstitutioncode, /*本方*/ I.COUNTERINSTITUTIONCODE counterinstitutioncode,/*对手方*/ I.OURCAPITALBANKNAME ourcapitalbankname, /*资金开户行*/ I.OURCAPITALACCOUNTNAME ourcapitalaccountname, /*资金账户户名*/ I.OURCAPITALACCOUNTNUMBER ourcapitalaccountnumber, /*资金账号*/ I.OURPAYMENTSYSTEMCODE ourpaymentsystemcode, /*支付系统行号*/ I.COUNTERCAPITALACCOUNTNAME countercapitalaccountname, /*对方资金账户户名*/ I.COUNTERCAPITALBANKNAME countercapitalbankname, /*对方资金开户行*/ I.COUNTERCAPITALACCOUNTNUMBER countercapitalaccountnumber, /*对方资金账号*/ I.COUNTERPAYMENTSYSTEMCODE counterpaymentsystemcode, /*对方支付系统行号*/ I.COUNTERDEPOSITACCOUNTNAME counterdepositaccountname, /*对方托管账户户名*/ I.COUNTERDEPOSITINSTITUTION counterdepositinstitution, /*对方托管机构*/ I.COUNTERDEPOSITACCOUNTNUMBER counterdepositaccountnumber, /*对方托管账号*/ I.OURINSTITUTIONCHINESESHORTNAME ourinstitutionchineseshortname,/*本方机构*/ I.INSTITUTIONCHINESESHORTNAME institutionchineseshortname,/*对手方机构*/ tr.ccy ccy, /*债券币种*/ 1 as exchangerate, /*汇率*/ iqcp.PLEDGE_RATIO as pledgeRate,/*折算比例%*/ QUOTE.SETT_TYPE as settType,/*清算类型*/ '' as settleStatus,/*净额清算状态*/ '' as repoMethod,/*回购方式*/ tpda.ENTRUST_ID entrustId, tpd.TRADE_ID tradeId, tpd.F_TRADE_ID fTradeId, tpd.R_TRADE_ID rTradeId, mcci2.PARTY_NAME cpPartyName,/*对手方机构*/ /*add by chenjiaxing 质押式回购改造 20210819 end*/ I.OURTRADERNAME ourTradeName,/*本方交易员*/ decode(I.BUSINESSTYPE,'BOND', (select TRADE_MARKET from fin_product where FINPROD_market_ID = ts.SECID), 'REPO',decode(tr.market, 'IB', '01', 'SH', '03', 'SZ', '04')) market, decode(decode(I.BUSINESSTYPE,'BOND',ts.SETTLE_SPEED,'REPO',tr.SETTLE_SPEED),'1','01','2','02','3','03') settleSpeed,/*清算速度*/ I.ourdepositaccountname ourdepositaccountname, I.EXECID execid /*成交编号*/ ,I.BUSINESSTYPE businesstype /*资产类型*/ ,decode(I.BUSINESSTYPE,'BOND',ts.SECID,'REPO','') securityid /*代码*/ ,decode(I.BUSINESSTYPE, 'BOND', I.SYMBOL, 'REPO', '') symbol /*简称*/ ,nvl(ts.ps,tr.ps) side ,ts.Prinamt prinamt ,tr.Repoamt repoamt ,I.LASTQTY lastqty/*券面总计（万）*/ ,tmi.SUMMATCHNUM lastqtyready
,decode(I.BUSINESSTYPE,'BOND',I.PRICE,'REPO',I.PRICE*100) price/*回购利率*/ ,decode(I.BUSINESSTYPE, 'BOND', I.DIRTYPRICE, 'REPO', '') dirtyprice ,decode(I.BUSINESSTYPE, 'BOND', I.UNDERLYINGYIELD2*100, 'REPO', '') underlyingyield2 ,I.TRADEDATE tradedate/*成交时间*/ ,decode(I.BUSINESSTYPE, 'BOND', I.ACCRUEDINTERESTAMT, 'REPO', '') accruedinterestamt ,I.ACCRUEDINTERESTTOTALAMT accruedinteresttotalamt/*回购利息*/ ,I.TRADECASHAMT tradecashamt/*交易金额*/ ,decode(I.BUSINESSTYPE, 'BOND', '', 'REPO', I.SETTLCURRAMT2) settlcurramt2/*到期结算金额*/ ,decode(I.BUSINESSTYPE, 'BOND', '', 'REPO', I.TRADELIMITDAYS) tradelimitdays/*回购期限*/ ,decode(I.BUSINESSTYPE, 'BOND', '', 'REPO', I.CASHHOLDINGDAYS) cashholdingdays/*实际占款天数*/ ,ROUND(NVL(decode(I.BUSINESSTYPE, 'BOND', NVL(tmi.SUMMATCHNUM*100, 0), 'REPO', NVL(tmi.SUMMATCHNUM, 0)), 0)/ NVL(DECODE(I.BUSINESSTYPE, 'BOND', I.LASTQTY, 'REPO', I.TRADECASHAMT), 1) , 4) percent, decode(I.BUSINESSTYPE, 'BOND', I.STRIKEYIELD*100, 'REPO', '') strikeyield, CASE WHEN tmi.SUMMATCHNUM IS NULL or tmi.SUMMATCHNUM=0 THEN '02' WHEN decode(I.BUSINESSTYPE, 'BOND', NVL(tmi.SUMMATCHNUM*100, 0), 'REPO', NVL(tmi.SUMMATCHNUM, 0)) = DECODE(I.BUSINESSTYPE, 'BOND', I.LASTQTY, 'REPO', I.TRADECASHAMT) then '01' ELSE '03' END matchStatus,/*匹配状态*/ QUOTE.QUOTEID reference,/*报价编号*/ /*QUOTE.ENTRUST_ID entrustId,*/ I.CB_FPRICE_AMT, I.SC_FPRICE_AMT, case when ipar.portfolio_id is not null then i.OURDEPOSITACCOUNTNUMBER else COUNTERDEPOSITACCOUNTNUMBER end as ourdepositaccountnumber, su.USER_NAME userName, I.OURDEPOSITINSTITUTION ourdepositinstitution, tpd.FINPROD_ID finprodId FROM INTERF_CSTP_TRADE I INNER JOIN (SELECT EXECID ,MAX(UPDATETIME) UPDATETIME FROM INTERF_CSTP_TRADE GROUP BY EXECID) II ON II.EXECID = I.EXECID AND II.UPDATETIME = I.UPDATETIME left join INTERF_OPICS_TRAD_REPO tr on tr.oritradeid = I.EXECID left join INTERF_TRAD_SECDEAL ts on ts.FEDEALNO = I.EXECID
LEFT JOIN MST_CFETS_CUSTOMER_INFO mcci ON I.OURINSTITUTIONCODE= mcci.PARTY_CUSTOMER_ID LEFT JOIN IBU_PORTFOLIO_ACCT_RELA ipar ON mcci.PARTY_ID =ipar.PARTY_ID LEFT JOIN SYS_USER_ADD sua ON nvl(ts.TRAD,tr.BUYTRADER) =sua.IBU_TRADER LEFT JOIN SYS_USER su ON sua.USER_ID =su.USER_ID LEFT JOIN ( SELECT SUM(MATCH_NUM) SUMMATCHNUM,CSTP_TRADE_ID FROM trd_match_info group by CSTP_TRADE_ID ) tmi on tmi.CSTP_TRADE_ID = I.EXECID LEFT JOIN ( SELECT i.EXECID ,listagg(nvl(iqb.ENTRUST_ID , nvl(iqc.ENTRUST_ID ,nvl(iqerb.ENTRUST_ID,iqerr.ENTRUST_ID) )), ',') WITHIN GROUP ( ORDER BY i.UPDATETIME DESC) AS ENTRUST_ID ,nvl(iqb.QUOTE_ID,iqc.QUOTE_ID) QUOTEID,iqc.SETT_TYPE FROM INTERF_CSTP_TRADE i LEFT JOIN IBU_QUOTE_BOND_DET iqbd ON i.EXECID = iqbd.EXECID LEFT JOIN IBU_QUOTE_BOND iqb ON iqbd.QUOTE_ID = iqb.QUOTE_ID LEFT JOIN IBU_QUOTE_ETR_RE iqerb ON iqb.QUOTE_ID = iqerb.QUOTE_ID LEFT JOIN IBU_QUOTE_CREP iqc ON i.EXECID = iqc.EXECID LEFT JOIN IBU_QUOTE_ETR_RE iqerr ON iqc.QUOTE_ID = iqerr.QUOTE_ID GROUP BY i.EXECID ,nvl(iqb.QUOTE_ID,iqc.QUOTE_ID),iqc.SETT_TYPE ) QUOTE ON QUOTE.EXECID=I.EXECID left join TRD_PRODUCT_DEAL tpd on I.EXECID = tpd.F_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD tpda ON tpda.TRADE_ID = tpd.TRADE_ID left join ETR_ENTRUST on ETR_ENTRUST.ENTRUST_ID = tpda.ENTRUST_ID left join ptl_portfolio on ptl_portfolio.portfolio_id = ETR_ENTRUST.Portfolio_Id LEFT JOIN (select a.QUOTE_ID, a.PLEDGE_RATIO, a.PLEDGE_AMT, b.FINPROD_MARKET_ID, b.FINPROD_ABBR from IBU_QUOTE_CREP_PLEDGE a left join FIN_PRODUCT b on b.FINPROD_ID = a.PLEDGE_FINPROD_ID)iqcp ON iqcp.QUOTE_ID = QUOTE.QUOTEID LEFT JOIN( SELECT C.PARTY_CUSTOMER_ID, C.PARTY_NAME, A.PARTY_ID FROM MST_CFETS_CUSTOMER_INFO A LEFT JOIN MST_CFETS_CUSTOMER_RELA B ON A.PARTY_ID = B.SPARTY_ID LEFT JOIN MST_CFETS_CUSTOMER_INFO C ON B.MPARTY_ID = C.PARTY_ID) mcci2 on mcci2.PARTY_ID = I.COUNTERINSTITUTIONCODE
AND I.BUSINESSTYPE in ('BOND','REPO')
AND I.BUSINESSTYPE = #{finprodType}
AND nvl(ts.ps,tr.ps) = #{ps}
AND (ts.SECID = #{finprodId} or ts.SECID = CONCAT(#{finprodId},'.IB'))
AND I.EXECID IN
#{item}
AND (TRADEDATE BETWEEN #{tradeDateBegin} AND #{tradeDateEnd})
AND to_date(TRADEDATE,'yyyy-mm-dd') >= to_date(#{entrustStartDate},'yyyy-mm-dd') AND to_date(TRADEDATE,'yyyy-mm-dd') <= to_date(#{entrustEndDate},'yyyy-mm-dd')
and I.OURDEPOSITACCOUNTNUMBER = #{secAcctId}
and I.OURTRADERNAME LIKE CONCAT('%',CONCAT(#{ourTradeName},'%'))
and I.TRADELIMITDAYS >=${repoTerm}
and I.TRADELIMITDAYS <= ${repoTerm2}
and I.TRADECASHAMT >=${priceAmt}
and I.TRADECASHAMT <= ${priceAmt2}
and (nvl(iqb.ENTRUST_ID ,nvl(iqerb.ENTRUST_ID ,nvl(iqc.ENTRUST_ID,iqerr.ENTRUST_ID ))) = #{entrustBusiCode} or nvl(iqb.ENTRUST_ID ,nvl(iqerb.ENTRUST_ID ,nvl(iqc.ENTRUST_ID,iqerr.ENTRUST_ID ))) is null )
and QUOTE.quoteId = #{quoteId}
and ts.SECID = #{entrustFinprodId}
and decode(I.BUSINESSTYPE,'BOND',ts.SETTLE_SPEED,'REPO',tr.SETTLE_SPEED) = #{entrustSettleSpeed}
and nvl(ts.ps,tr.ps) = #{entrustPs}
and I.TRADELIMITDAYS = #{entrustTradelimitdays}
) aa
AND aa.matchStatus IN
#{item}
and aa.market = #{tradeMarket}
and aa.settleSpeed = #{settleSpeed}
and aa.tradelimitdays = #{tradelimitdays}
